'use strict';
// Interaction sketch only. Synthetic state; no fetch, API, production data or storage.
const steps=['Sample identity and completed drying record verified','Required preparation steps completed according to the applicable laboratory procedure','Prepared material and retained portions labelled for their intended analyses'];
let state;let view='bench';let lane='work';let method='prep';
const $=s=>document.querySelector(s);
function reset(gap=false){clearTimeout(window.noticeTimer);$('#notice').style.display='none';state={gap,checks:[false,false,false],prep:gap?'gap':'draft',operationAt:null,values:Array(40).fill(''),resultStates:Array(40).fill('draft'),selected:Array(40).fill(true),receipt:null};view='bench';lane='work';method='prep';render();}
function notice(t){$('#notice').textContent=t;$('#notice').style.display='block';clearTimeout(window.noticeTimer);window.noticeTimer=setTimeout(()=>$('#notice').style.display='none',5500);}
function tag(text,kind=''){return `<span class="tag ${kind}">${text}</span>`;}
function count(status){return state.resultStates.filter(s=>s===status).length;}
function sampleName(i){return `DEMO-${String(i+1).padStart(3,'0')}`;}
function heading(title,subtitle,right=''){return `<div class="title-row"><div><span class="eyebrow">GTM LABORATORY · SYNTHETIC WORK</span><h1>${title}</h1><div class="muted">${subtitle}</div></div>${right}</div>`;}
function prepLabel(){return state.prep==='done'?'Preparation completed':state.gap?'Evidence needs verification':'Preparation in progress';}
function modal(title,body){$('#detail-body').innerHTML=`<h2>${title}</h2>${body}`;$('#details').showModal();}
function evidence(){modal('Preparation record',state.prep==='done'?`<p>DEMO-001 · recorded by Demo technician · ${state.operationAt}</p><p class="small">Demonstration procedure · operational-checklist-v1</p><ul>${steps.map(s=>`<li>Confirmed — ${s}</li>`).join('')}</ul><p>This evidence is shared by Workbench and the Sample record. There is no second checklist to fill.</p>`:'<p>The legacy record says Done, but it does not contain a checklist. Missing evidence is not equivalent to work that was never performed.</p><p>Resolve through a documented verification or a new authorized preparation attempt.</p>');}
function recovery(){modal('Resolve the legacy record',`<p>This proposal preserves the original completion record and makes the uncertainty visible.</p><ol><li>Manager checks the original order against assigned work.</li><li>Locate contemporaneous preparation records.</li><li>If supported, record retrospective verification with the source and current verification time. Otherwise authorize a new attempt.</li><li>Assess any dependent measurements before releasing the block.</li></ol><p><strong>No automatic checklist answers or scientific approval.</strong></p>`);}
function render(){document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#main').innerHTML=view==='bench'?bench():view==='sample'?sample():manager();bind();}
function bench(){return heading('My workbench','Prepare material, record results and send completed work for review.',tag('Demo technician','neutral'))+`<div class="tabs" role="navigation" aria-label="Work queues">${[['work','My work'],['submit',`Ready to submit · ${count('recorded')}`],['sent',`Sent & completed · ${count('submitted')+count('accepted')+(state.prep==='done'?1:0)}`]].map(([key,label])=>`<button data-lane="${key}" class="${lane===key?'active':''}">${label}</button>`).join('')}</div>`+(lane==='work'?`<div class="toolbar"><label>Working on <select id="method"><option value="prep" ${method==='prep'?'selected':''}>Sample preparation · DEMO-001</option><option value="ph" ${method==='ph'?'selected':''}>pH in water · rack of 40 samples</option></select></label><span class="small">One compatible procedure / method per worksheet</span></div>${method==='prep'?prep():ph()}`:lane==='submit'?submission():sent());}
function prep(){return `<div class="panel"><div class="panel-head"><div><h2>Sample preparation</h2><span class="small">DEMO-001 · applicable procedure · operational-checklist-v1</span></div>${tag(prepLabel(),state.gap?'warn':state.prep==='done'?'':'neutral')}</div><div class="panel-body"><div class="step-grid"><div class="operation"><span class="step-no">1</span><div><h3>Drying</h3>${tag('Completed')}<p>Saved operational evidence is available.</p></div></div><div class="operation"><span class="step-no">2</span><div><h3>Preparation</h3>${tag(prepLabel(),state.gap?'warn':'neutral')}<p>Confirm only the work you have performed.</p></div></div></div>${state.gap?`<div class="alert"><strong>Completion exists; evidence is missing</strong>The legacy value is “Done”. Keep that history. Dependent result entry is paused until the record is assessed.</div><button id="recover">View recovery path</button>`:state.prep==='done'?`<div class="receipt"><strong>Preparation completed · DEMO-001</strong><p>3 checks confirmed by Demo technician at ${state.operationAt}.</p><p>No scientific submission is needed for this routine operation.</p></div><button id="evidence">View saved checklist</button>`:`<div class="checklist">${steps.map((s,i)=>`<label><input type="checkbox" data-check="${i}" ${state.checks[i]?'checked':''}>${s}</label>`).join('')}</div><p class="small">The production form must come from the lab's actual SOP. This sketch does not prescribe drying temperature or sieve size.</p>`}</div><div class="foot"><span class="small">${state.prep==='done'?'Saved evidence is shown on the Sample record.':state.gap?'Manager action required; no repeat submission.':`${state.checks.filter(Boolean).length} of 3 checks confirmed · demo draft`}</span>${state.prep==='done'?'<button id="next-method" class="primary">Open pH worksheet →</button>':`<button id="confirm" class="primary" ${state.gap||!state.checks.every(Boolean)?'disabled':''}>Confirm preparation complete</button>`}</div></div>`;}
function ph(){let editable=state.prep==='done';return `<div class="panel"><div class="panel-head"><div><h2>pH in water · 40 samples</h2><span class="small">Illustrative method revision 1 · same preparation and basis · rack A</span></div><button id="demo-readings" ${!editable?'disabled':''}>Load demo readings</button></div>${!editable?'<div class="panel-body"><div class="alert"><strong>Preparation blocks entry</strong>Complete or resolve preparation before recording laboratory measurements.</div></div>':''}<div class="scroll" tabindex="0" aria-label="Forty-sample pH worksheet"><table><thead><tr><th>Select</th><th>Sample / position</th><th>pH</th><th>State</th></tr></thead><tbody>${state.values.map((v,i)=>`<tr><td><input type="checkbox" aria-label="Select ${sampleName(i)}" data-select="${i}" ${state.selected[i]?'checked':''} ${state.resultStates[i]!=='draft'?'disabled':''}></td><td>${sampleName(i)} <span class="small"> · ${i+1}</span></td><td><input type="number" step=".01" min="0" max="14" value="${v}" aria-label="${sampleName(i)} pH" data-value="${i}" ${!editable||state.resultStates[i]!=='draft'?'disabled':''}></td><td>${tag(state.resultStates[i]==='draft'?(v===''?'Awaiting reading':'Demo draft'):state.resultStates[i]==='recorded'?'Ready to submit':state.resultStates[i]==='submitted'?'Sent for review':'Accepted','neutral')}</td></tr>`).join('')}</tbody></table></div><div class="foot"><span class="small">Select exact samples · recorded rows remain available for submission</span><button class="primary" id="record" ${!editable?'disabled':''}>Record selected readings</button></div></div>`;}
function submission(){let n=count('recorded');return `<div class="panel"><div class="panel-head"><div><h2>Ready to send for scientific review</h2><p class="small">This queue loads independently of unfinished tasks.</p></div>${tag(`${n} determinations`,'neutral')}</div>${n?`<div class="panel-body"><p><strong>${n} samples · pH in water · illustrative method revision 1</strong></p><p>Only these recorded pH attempts will be submitted. Preparation records are not included.</p><div class="scroll" tabindex="0" aria-label="Exact submission contents"><table><thead><tr><th>Sample</th><th>Recorded pH</th><th>Review state</th></tr></thead><tbody>${state.values.map((v,i)=>state.resultStates[i]==='recorded'?`<tr><td>${sampleName(i)}</td><td>${v}</td><td>Not yet submitted</td></tr>`:'').join('')}</tbody></table></div></div><div class="foot"><span class="small">Demonstration selects all the items listed above.</span><button id="send" class="primary">Send ${n} determinations for review</button></div>`:'<div class="empty">No recorded scientific work is waiting for submission.<br>Preparation completion appears under Sent & completed.</div>'}</div>`;}
function sent(){return `<div class="panel"><div class="panel-head"><h2>Sent and completed work</h2><button id="reload-view">Reload this view</button></div><div class="panel-body">${state.prep==='done'?`<div class="receipt"><strong>DEMO-001 · preparation completed</strong><p>3/3 confirmed · Demo technician · ${state.operationAt}</p><button class="link" id="evidence">View saved evidence</button></div>`:''}${count('submitted')||count('accepted')?`<div class="receipt"><strong>${count('submitted')+count('accepted')} pH determinations</strong><p>${count('submitted')} awaiting scientific review · ${count('accepted')} accepted</p></div>`:'<p class="muted">No scientific submissions yet.</p>'}</div></div>`;}
function sample(){return heading('DEMO-001','Sample record · evidence and progress',`<button id="open-workbench" class="primary">Open in Workbench →</button>`)+(state.gap?'<div class="alert"><strong>Order and preparation need attention</strong>In the W001-shaped scenario, the active order and assigned tasks disagree and preparation evidence is missing. Do not approve or relabel either set automatically.</div>':'')+`<div class="step-grid"><div class="panel"><div class="panel-head"><h2>Preparation</h2>${tag(prepLabel(),state.gap?'warn':'neutral')}</div><div class="panel-body"><p>Drying: completed</p><p>Preparation: ${state.prep==='done'?'3 of 3 checks confirmed':state.gap?'Legacy completion — evidence gap':'In progress'}</p><p class="small">${state.operationAt?`Demo technician · ${state.operationAt}`:'No confirmed preparation evidence in this demonstration yet.'}</p>${state.prep==='done'||state.gap?'<button class="link" id="evidence">Inspect evidence</button>':''}</div></div><div class="panel"><div class="panel-head"><h2>Scientific work</h2></div><div class="panel-body"><p>pH in water · illustrative method revision 1</p><p>${state.values[0]&&state.resultStates[0]!=='draft'?`Recorded result: <strong>${state.values[0]}</strong>`:'No recorded result yet. Technician drafts are not reported as results.'}</p><p>${tag(state.resultStates[0]==='draft'?'Awaiting record':state.resultStates[0]==='recorded'?'Ready to submit':state.resultStates[0]==='submitted'?'Submitted for review':'Accepted','neutral')}</p></div></div></div><div class="panel"><div class="panel-head"><h2>Evidence history</h2><span class="small">Read-only execution view</span></div><div class="panel-body"><p>Recorded operations, scientific attempts, decisions and amendments appear here with their original evidence versions.</p><p class="small">Intake, assignment, custody, labels, map, order management and authorized review remain separate controls in the implementation; this focused sketch does not recreate those screens.</p></div></div>`;}
function manager(){return heading('Review work','Inspect the recorded evidence before making a decision.',tag('Reviewer preview','neutral'))+(state.gap?`<div class="alert"><strong>DEMO-001 · record integrity needs attention</strong>Legacy preparation has no checklist. Active order and assigned tasks require reconciliation.</div><button id="recover">Open recovery instructions</button>`:`<div class="receipt"><strong>Routine preparation has its own completion record.</strong><p>${state.prep==='done'?'DEMO-001 is prepared. No scientific approval button is needed for this operation.':'Preparation has not yet been confirmed.'}</p></div>`)+`<div class="panel"><div class="panel-head"><h2>Submitted scientific results · ${count('submitted')}</h2></div><div class="panel-body">${count('submitted')?`<p>${count('submitted')} pH determinations submitted by Demo technician.</p><p class="small">This sketch assumes the synthetic evidence and QC are valid. Production must verify exact versions, authorization, active order and QC at commit.</p><button id="accept" class="primary" ${state.gap?'disabled':''}>Accept submitted demo results</button>`:'<p class="muted">No scientific results currently submitted for review.</p><p class="small">Recorded but unsubmitted work belongs in the technician’s Ready to submit queue.</p>'}</div></div>`;}
function bind(){document.querySelectorAll('[data-lane]').forEach(b=>b.onclick=()=>{lane=b.dataset.lane;render();});if($('#method'))$('#method').onchange=e=>{method=e.target.value;render();};document.querySelectorAll('[data-check]').forEach(c=>c.onchange=()=>{state.checks[+c.dataset.check]=c.checked;const focus=+c.dataset.check;render();document.querySelector(`[data-check="${focus}"]`).focus();});document.querySelectorAll('[data-value]').forEach(e=>e.onchange=()=>{state.values[+e.dataset.value]=e.value;});document.querySelectorAll('[data-select]').forEach(e=>e.onchange=()=>state.selected[+e.dataset.select]=e.checked);
const actions={confirm:()=>{if(state.gap||!state.checks.every(Boolean))return;state.prep='done';state.operationAt=new Date().toLocaleTimeString();render();notice('Preparation confirmed once. Open the Sample record to see the same evidence.');},'next-method':()=>{method='ph';render();},evidence,recover:recovery,'demo-readings':()=>{state.values=state.values.map((v,i)=>state.resultStates[i]==='draft'?(6+i%9/10).toFixed(2):v);render();notice('Synthetic demonstration readings loaded; not instrument data.');},record:()=>{let n=0,bad=0;state.values.forEach((v,i)=>{if(!state.selected[i]||state.resultStates[i]!=='draft')return;if(v.trim()===''||!Number.isFinite(Number(v))||+v<0||+v>14){bad++;return;}state.resultStates[i]='recorded';n++;});lane=n?'submit':'work';render();notice(`${n} recorded; ${bad} empty or invalid rows retained. ${n?'The submission queue remains available.':'Nothing was recorded.'}`);},send:()=>{let n=count('recorded');state.resultStates=state.resultStates.map(s=>s==='recorded'?'submitted':s);lane='sent';render();notice(`${n} scientific determinations sent for review. No preparation tasks included.`);},'reload-view':()=>{render();notice('View rebuilt from the same synthetic saved record. Browser reload resets this standalone demo.');},'open-workbench':()=>{view='bench';method='prep';lane='work';render();},accept:()=>{state.resultStates=state.resultStates.map(s=>s==='submitted'?'accepted':s);render();notice('Synthetic submitted results accepted. Inspect the Sample record.');}};Object.entries(actions).forEach(([id,fn])=>{if($('#'+id))$('#'+id).onclick=fn;});}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;render();});$('#scenario').onchange=e=>reset(e.target.value==='gap');$('#reset').onclick=()=>reset($('#scenario').value==='gap');window.workPrototype={getState:()=>JSON.parse(JSON.stringify(state))};reset();
